  "롯데건설": {
    updated: `2026-09-02`,
    programs: [
      `mom편한 꿈다락 — 2017~ 9년차. 지역아동센터 환경개선 + 코딩·AI·디지털 리터러시, AR/VR 공간디자인, 3D펜. 총 93개소(2026년은 3개소 선정)`,
      `청춘책방 — 2016~, 89개소 누적 4,200명. 육·해·공군본부 통해 부대 선정, 북콘서트·저자강연 병행`,
      `밸유 for ESG — 대학생 사회공헌. 봉사자 243명, 465회, 대상자 6,053명`,
      `롯데하이마트 Hi과학콘서트·Hi과학교실 — 2018~ 누적 약 5,000명`,
      `롯데홈쇼핑 크리에이터 클래스 — 라이브커머스 이론·실무·채용 연계, 2025년말까지 200명 이상 수료`,
      `롯데장학재단 북드림 — 2015~ 누적 1,095개교·33억원 상당`,
      `롯데복지재단 다문화 엄마학교`,
    ],
    structure: `【롯데 그룹 공통】 **⚠️ 롯데재단이 계열사 공통 창구라는 구조는 근거를 찾지 못했음.** 실제로는 두 라인이 분리돼 있음. ① **롯데지주 CSV팀**이 그룹 공통 브랜드(mom편한·청춘책방·밸유 for ESG 등)를 기획·예산 지원하고 **현장 운영은 외부 비영리기관에 위탁**. ② **롯데재단**(장학1983+복지1994+삼동복지2009)은 창업주 사재 출연 별도 법인으로 장학·복지를 직접 공모·집행. 롯데문화재단은 별개 법인. ③ 계열사는 각자 별도 파트너와 직접 협약. 최대 수행기관은 **구세군자선냄비본부**(꿈다락·청춘책방·생명틔움·조손가꿈). 그 외 초록우산(mom편한 놀이터·하이마트 과학교실), 한경협중소기업협력센터(홈쇼핑 크리에이터 클래스), 세이브더칠드런(웰푸드 해피홈), 서울시 경계선지능인 평생교육지원센터(글로벌로지스), 지파운데이션(물산), 유니세프(호텔롯데).`,
    contact: `롯데재단 사업신청 포털 https://portal.lottefoundation.or.kr (수혜자 신청용, 수행기관 공모 아님) · scholarship@lotte.net · **구세군 꿈다락 담당 02-6364-4097 / momdarak@redkettle.kr** · 롯데지주 CSV팀 직접 제안창구는 확인 못 함`,
    kmaAngle: `① **구세군자선냄비본부 새소식 게시판이 실질 입찰 창구.** 기업 CSR 교육사업의 참여기관 모집·용역 입찰이 상시 게시됨 (인동에프엔 진로탐색 입찰, SBI저축은행 디지털 금융안전 체험교육 참여기관 모집 등). 꿈다락이 2026년부터 AI 콘텐츠·AR/VR·3D펜을 넣었는데 **구세군은 복지기관이지 교육콘텐츠 기관이 아님** → 교육과정 설계·강사 수급·현장 운영이 외주화될 개연성이 큼. ② **롯데홈쇼핑 크리에이터 클래스는 교육 전문기관 위탁 선례** — 한경협중소기업협력센터. 롯데가 교육사업을 교육기관에 맡긴다는 증거. 채용 연계·수료생 성과관리가 명시돼 있어 KMA 성과관리 방법론이 붙기 좋음. ③ 하이마트 Hi과학교실은 협력기관이 초록우산(모금·아동복지 전문) — 강사 양성·표준 커리큘럼·성과측정이 빈자리.`,
    sources: [
      `https://www.lotte.co.kr/csv/main.do`,
      `https://lottefoundation.or.kr/business`,
      `https://portal.lottefoundation.or.kr/`,
      `https://www.thesalvationarmy.or.kr/story/news`,
      `https://zdnet.co.kr/view/?no=20260731170308`,
      `https://www.youthdaily.co.kr/news/article.html?no=220374`,
    ],
    unknown: [
      `롯데지주 개인정보처리방침의 수탁자는 롯데이노베이트(전산) 1곳뿐 — 사회공헌 위탁사 목록은 비공개`,
      `밸유 for ESG 수행기관 (공식 페이지에 협력기관란 자체가 없음)`,
      `롯데정밀화학·롯데렌탈·롯데캐피탈·롯데지알에스의 교육사업 및 수행기관 — 확인 못 함`,
      `각 사업의 예산 규모·계약 방식(수의/입찰)·계약 기간`,
      `종료된 프로그램 — 종료 연도가 명시된 교육사업을 찾지 못함`,
    ],
  },

